const DEFAULT_COVERAGE_THRESHOLD = 0.005;

// Controller-local expiry rejects. Leave headroom for a timely evaluated Verdict;
// snapshot upload happens after the control attempt and does not consume this budget.
const VERDICT_WINDOW_MS = 3000;
const MODEL_PROMPT_TIMEOUT_MS = 250;
const CAPTURE_TIMEOUT_MS = 800;
const SNAPSHOT_UPLOAD_TIMEOUT_MS = 300;
const MODEL_TIMEOUT_MS = 1200;
const VERDICT_POST_TIMEOUT_MS = 250;
const PRE_VERDICT_BUDGET_MS =
  MODEL_PROMPT_TIMEOUT_MS +
  CAPTURE_TIMEOUT_MS +
  MODEL_TIMEOUT_MS;

const MODEL_SUCCESS_STATUS = "success";
const DEFAULT_DETECTION_LABEL = "defect";

const VERDICT = Object.freeze({ PASS: "pass", REJECT: "reject" });

const FailureReason = Object.freeze({
  MODEL_TIMEOUT: "model_timeout",
  MODEL_UNREACHABLE: "model_unreachable",
  MODEL_HTTP_ERROR: "model_http_error",
  MODEL_INVALID_RESPONSE: "model_invalid_response",
  MODEL_STATUS_MISSING: "model_status_missing",
  MODEL_ERROR_STATUS: "model_error_status",
  MODEL_INSTRUCTION_MISSING: "model_instruction_missing",
  MODEL_INVALID_BOX: "model_invalid_box",
  FRAME_CAPTURE_FAILED: "frame_capture_failed",
  FRAME_CONTEXT_INVALID: "frame_context_invalid",
  INVALID_THRESHOLD: "invalid_threshold",
  INVALID_VERDICT_BUDGET: "invalid_verdict_budget"
});

const REASON_NO_DEFECT = "no_defect_detected";
const REASON_DEFECT = "defect_detected";

// A forced reject is an operational error, not a successful inspection.
function buildInspectionResponse(decision) {
  const evaluated = decision &&
    [REASON_DEFECT, REASON_NO_DEFECT].includes(decision.reason) &&
    [VERDICT.PASS, VERDICT.REJECT].includes(decision.verdict);
  return evaluated
    ? { status: "success", result: decision.verdict }
    : { status: "error", result: "error", reason: decision?.reason ?? FailureReason.MODEL_INVALID_RESPONSE };
}

const FRAME_HEADERS = Object.freeze({
  sessionId: "x-camera-session",
  sequence: "x-frame-sequence",
  capturedAt: "x-captured-at",
  width: "x-frame-width",
  height: "x-frame-height"
});

function asFiniteNumber(value) {
  if (
    value === null ||
    value === undefined ||
    typeof value === "boolean" ||
    (typeof value === "string" && value.trim() === "")
  ) {
    return null;
  }
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function readHeader(headers, name) {
  if (!headers || typeof headers !== "object") return null;
  const key = Object.keys(headers).find((candidate) => candidate.toLowerCase() === name);
  if (key === undefined) return null;
  const value = headers[key];
  const first = Array.isArray(value) ? value[0] : value;
  if (first === null || first === undefined) return null;
  return String(first);
}

function readTrimmed(header) {
  return header && header.trim() ? header.trim() : null;
}

function boxArea(box) {
  if (!Array.isArray(box) || box.length < 4) return 0;
  const coords = box.slice(0, 4).map(asFiniteNumber);
  if (coords.some((value) => value === null)) return 0;
  const [x1, y1, x2, y2] = coords;
  return Math.max(0, x2 - x1) * Math.max(0, y2 - y1);
}

// Overlapping boxes are summed rather than unioned: the figure is a relative
// signal, so the clamp to 1 is what keeps it a fraction of the frame.
function defectCoverage(detections, frameWidth, frameHeight) {
  const width = asFiniteNumber(frameWidth);
  const height = asFiniteNumber(frameHeight);
  if (width === null || height === null || width <= 0 || height <= 0) return null;

  const frameArea = width * height;
  if (!Number.isFinite(frameArea) || frameArea <= 0) return null;

  const boxes = Array.isArray(detections) ? detections : [];
  const covered = boxes.reduce((total, candidate) => {
    const box = candidate && typeof candidate === "object" && "box" in candidate ? candidate.box : candidate;
    return total + boxArea(box);
  }, 0);

  return Math.min(1, Math.max(0, covered / frameArea));
}

// A coverage figure or threshold we cannot read is treated as suspect rather
// than clean: `coverage >= NaN` would otherwise pass every item.
function decideVerdict(coverage, threshold) {
  const limit = asFiniteNumber(threshold);
  const value = asFiniteNumber(coverage);
  if (limit === null || limit < 0) return VERDICT.REJECT;
  if (value === null) return VERDICT.REJECT;
  return value >= limit ? VERDICT.REJECT : VERDICT.PASS;
}

function parseFrameContext(headers) {
  return {
    sessionId: readTrimmed(readHeader(headers, FRAME_HEADERS.sessionId)),
    sequence: asFiniteNumber(readHeader(headers, FRAME_HEADERS.sequence)),
    capturedAt: readTrimmed(readHeader(headers, FRAME_HEADERS.capturedAt)),
    width: asFiniteNumber(readHeader(headers, FRAME_HEADERS.width)),
    height: asFiniteNumber(readHeader(headers, FRAME_HEADERS.height))
  };
}

function hasUsableFrameGeometry(frameContext) {
  if (!frameContext || typeof frameContext !== "object") return false;
  const width = asFiniteNumber(frameContext.width);
  const height = asFiniteNumber(frameContext.height);
  return width !== null && height !== null && width > 0 && height > 0;
}

// Mirrors the HUD parser's own box rule (x2 > x1, y2 > y1) so a box we accept
// is always a box the overlay can render.
function readRenderableBox(candidate) {
  if (!candidate || typeof candidate !== "object") return null;
  if (!Array.isArray(candidate.box) || candidate.box.length < 4) return null;
  const coords = candidate.box.slice(0, 4).map(asFiniteNumber);
  if (coords.some((value) => value === null)) return null;
  const [x1, y1, x2, y2] = coords;
  if (x2 <= x1 || y2 <= y1) return null;
  return coords;
}

function readLabel(candidate) {
  const label = candidate.label;
  if (typeof label !== "string") return DEFAULT_DETECTION_LABEL;
  return label.trim() ? label.trim() : DEFAULT_DETECTION_LABEL;
}

function rejected(reason, overrides = {}) {
  return {
    verdict: VERDICT.REJECT,
    reason,
    coverage: null,
    coverageThreshold: null,
    boxCount: 0,
    detections: [],
    promptVerified: null,
    promptUsed: null,
    promptMismatch: false,
    ...overrides
  };
}

function readCoverageThreshold(threshold) {
  if (threshold === undefined) return DEFAULT_COVERAGE_THRESHOLD;
  const value = asFiniteNumber(threshold);
  return value !== null && value >= 0 ? value : null;
}

function verifyPrompt(response, instruction) {
  const promptUsed = typeof response.prompt_used === "string" && response.prompt_used.trim()
    ? response.prompt_used
    : null;
  const expected = typeof instruction === "string" && instruction.trim() ? instruction : null;

  if (promptUsed === null || expected === null) {
    return { promptVerified: null, promptUsed, promptMismatch: false };
  }
  const verified = promptUsed === expected;
  return { promptVerified: verified, promptUsed, promptMismatch: !verified };
}

const UNREACHABLE_PATTERN = /ECONNREFUSED|ENOTFOUND|EHOSTUNREACH|ENETUNREACH|fetch failed|socket hang up/i;
const TIMEOUT_PATTERN = /timed?\s*out|timeout|ETIMEDOUT|ESOCKETTIMEDOUT/i;

// n8n hands an HTTP failure back as an error item. Mapping it here means the
// fail-safe reasons are decided by tested code, not by node configuration.
function classifyModelOutcome(json) {
  const error = json?.error;
  if (error === undefined || error === null) {
    return { kind: "ok", response: json };
  }

  const detail = String(typeof error === "string" ? error : error?.message ?? error ?? "");
  const reason = TIMEOUT_PATTERN.test(detail)
    ? FailureReason.MODEL_TIMEOUT
    : UNREACHABLE_PATTERN.test(detail)
      ? FailureReason.MODEL_UNREACHABLE
      : FailureReason.MODEL_HTTP_ERROR;

  return { kind: "failure", reason, detail };
}

function suppressionKey(frameContext) {
  if (!frameContext || typeof frameContext !== "object") return null;
  const sessionId = readTrimmed(frameContext.sessionId);
  const sequence = asFiniteNumber(frameContext.sequence);
  if (!sessionId || sequence === null) return null;
  return `${sessionId}:${sequence}`;
}

function shouldSuppressDuplicate(store, frameContext, nowMs, windowMs = VERDICT_WINDOW_MS) {
  const key = suppressionKey(frameContext);
  if (!key) return false;

  const target = store && typeof store === "object" ? store : {};
  const now = asFiniteNumber(nowMs) ?? Date.now();
  for (const [oldKey, at] of Object.entries(target.lastVerdictAt ?? {})) {
    if (now - at >= windowMs) delete target.lastVerdictAt[oldKey];
  }
  const last = target.lastVerdictAt?.[key];
  if (typeof last === "number" && now - last < windowMs) return true;

  target.lastVerdictAt = target.lastVerdictAt ?? {};
  target.lastVerdictAt[key] = now;
  return false;
}

const UNSAFE_NAME_CHARS = /[^A-Za-z0-9._-]/g;

function buildSnapshotObjectName(frameContext) {
  const session = readTrimmed(frameContext?.sessionId) ?? "frame";
  const sequence = asFiniteNumber(frameContext?.sequence);
  const stamp = sequence === null ? "unknown" : String(sequence);
  return `${session}-${stamp}.jpg`.replace(UNSAFE_NAME_CHARS, "-");
}

// The workflow ships the timeout as REPLACE_MODEL_TIMEOUT_MS so it can be tuned
// per deployment. Whatever it becomes, the whole pre-verdict path has to leave
// headroom inside the ESP32 Verdict Window, so the budget is checked rather
// than assumed. An unreadable value falls back to the shipped default instead
// of disabling the check — but the substitution is reported, never silent,
// because a configured value that quietly went unread is a deployment fault.
function resolveVerdictBudget(configuredModelTimeoutMs, windowMs = VERDICT_WINDOW_MS) {
  const requested = asFiniteNumber(configuredModelTimeoutMs);
  const readable = requested !== null && requested > 0;
  const modelTimeoutMs = readable ? requested : MODEL_TIMEOUT_MS;
  const totalMs =
    PRE_VERDICT_BUDGET_MS - MODEL_TIMEOUT_MS + modelTimeoutMs + VERDICT_POST_TIMEOUT_MS;
  const fits = totalMs < windowMs;

  return {
    configured: configuredModelTimeoutMs ?? null,
    readable,
    substituted: !readable,
    modelTimeoutMs,
    // Configuration arithmetic is a guard, not evidence of physical timing.
    appliedModelTimeoutMs: fits ? modelTimeoutMs : MODEL_TIMEOUT_MS,
    totalMs,
    fits
  };
}

// The Coverage Threshold decides pass or reject, so an unreadable configured
// value must not be guessed at. An unconfigured placeholder falls back to the
// documented default; a value that was set but cannot be read is a fault and is
// returned as null so the decision fails closed with `invalid_threshold`.
function resolveCoverageThreshold(configuredThreshold) {
  const raw = typeof configuredThreshold === "string" ? configuredThreshold.trim() : configuredThreshold;

  if (raw === null || raw === undefined || raw === "") {
    return { value: DEFAULT_COVERAGE_THRESHOLD, configured: null, readable: true, defaulted: true };
  }
  if (typeof raw === "string" && raw.startsWith("REPLACE_")) {
    return { value: DEFAULT_COVERAGE_THRESHOLD, configured: raw, readable: true, defaulted: true };
  }

  const value = asFiniteNumber(raw);
  if (value === null || value < 0 || value > 1) {
    return { value: null, configured: raw, readable: false, defaulted: false };
  }

  return { value, configured: raw, readable: true, defaulted: false };
}

// Both watchdog probes read a different response shape but share one rule: a
// throw is a failure, and only a well-formed answer can be healthy.
function buildHealthProbe(component, readDetail, isHealthy) {
  try {
    const detail = readDetail();
    return { component, healthy: isHealthy(detail) === true, detail, error: null };
  } catch (error) {
    return { component, healthy: false, detail: null, error: String(error?.message ?? error) };
  }
}

function buildInspectionDecision({
  outcome,
  frameContext,
  instruction,
  threshold,
  budget,
  frameCaptureFailed = false
} = {}) {
  // A dead Pi is its own failure, and naming it keeps it out of the model's
  // failure reasons where it would be misread as a model problem. There are no
  // boxes to show in this case: the frame never arrived.
  if (frameCaptureFailed) {
    return rejected(FailureReason.FRAME_CAPTURE_FAILED);
  }

  const coverageThreshold = readCoverageThreshold(threshold);
  if (coverageThreshold === null) {
    return rejected(FailureReason.INVALID_THRESHOLD);
  }

  if (!outcome || typeof outcome !== "object") {
    return rejected(FailureReason.MODEL_INVALID_RESPONSE);
  }
  if (outcome.kind === "failure") {
    return rejected(outcome.reason || FailureReason.MODEL_UNREACHABLE, { coverageThreshold });
  }
  if (outcome.kind !== "ok") {
    return rejected(FailureReason.MODEL_INVALID_RESPONSE, { coverageThreshold });
  }

  const response = outcome.response;
  if (!response || typeof response !== "object" || Array.isArray(response)) {
    return rejected(FailureReason.MODEL_INVALID_RESPONSE, { coverageThreshold });
  }
  if (typeof response.status !== "string" || !response.status.trim()) {
    return rejected(FailureReason.MODEL_STATUS_MISSING, { coverageThreshold });
  }
  if (response.status !== MODEL_SUCCESS_STATUS) {
    return rejected(FailureReason.MODEL_ERROR_STATUS, { coverageThreshold });
  }
  if (!Array.isArray(response.detections)) {
    return rejected(FailureReason.MODEL_INVALID_RESPONSE, { coverageThreshold });
  }
  if (!hasUsableFrameGeometry(frameContext)) {
    return rejected(FailureReason.FRAME_CONTEXT_INVALID, { coverageThreshold });
  }

  const detections = [];
  for (const candidate of response.detections) {
    const box = readRenderableBox(candidate);
    if (box === null) {
      return rejected(FailureReason.MODEL_INVALID_BOX, { coverageThreshold });
    }
    detections.push({ label: readLabel(candidate), box });
  }

  const coverage = defectCoverage(detections, frameContext.width, frameContext.height);
  const prompt = verifyPrompt(response, instruction);

  // Boxes found under an instruction nobody can name are not a verdict, but they
  // are still what the operator needs to see — the threshold never hides a box.
  // So the boxes are parsed first and the Verdict is forced afterwards.
  const instructionMissing = typeof instruction !== "string" || !instruction.trim();
  if (instructionMissing) {
    return {
      ...rejected(FailureReason.MODEL_INSTRUCTION_MISSING, { coverageThreshold }),
      coverage,
      boxCount: detections.length,
      detections,
      ...prompt
    };
  }

  // A budget that cannot fit is a setup error, but it is still a reject. The
  // measured figures and the boxes survive so the operator can see what the
  // model found; only the physical path is forced.
  const budgetFits = budget?.fits !== false;
  const verdict = budgetFits ? decideVerdict(coverage, coverageThreshold) : VERDICT.REJECT;

  return {
    verdict,
    reason: budgetFits
      ? verdict === VERDICT.REJECT
        ? REASON_DEFECT
        : REASON_NO_DEFECT
      : FailureReason.INVALID_VERDICT_BUDGET,
    coverage,
    coverageThreshold,
    boxCount: detections.length,
    detections,
    ...prompt
  };
}



const MODEL_INSTRUCTION_TEMPLATE =
  "Locate all the instances that matches the following description: {target}.";

const HUD_MESSAGE_TYPE = "detections";
const HUD_COORDINATE_SPACE = "pixel";

const TRAILING_SENTENCE_PUNCTUATION = /[.!?]+$/;

function trimmed(value) {
  return typeof value === "string" ? value.trim() : "";
}

// The exact grammar is part of the model contract, so the target is normalised
// here once and every consumer gets an identical instruction.
function buildModelInstruction(target) {
  const normalized = trimmed(target).replace(TRAILING_SENTENCE_PUNCTUATION, "").trim();
  if (!normalized) return null;
  return MODEL_INSTRUCTION_TEMPLATE.replace("{target}", normalized);
}

// Recovering the target from the instruction is the inverse of the builder, so
// it is derived from the same template rather than split on a hand-written
// delimiter. An instruction that is not the canonical shape yields null: a
// guess would write the operator's own words into the Inspection Result wrong.
const [TEMPLATE_PREFIX, TEMPLATE_SUFFIX] = MODEL_INSTRUCTION_TEMPLATE.split("{target}");

function parseInspectionTarget(instruction) {
  if (typeof instruction !== "string") return null;
  const candidate = instruction.trim();
  if (candidate.length <= TEMPLATE_PREFIX.length + TEMPLATE_SUFFIX.length) return null;
  if (!candidate.startsWith(TEMPLATE_PREFIX)) return null;
  if (!candidate.endsWith(TEMPLATE_SUFFIX)) return null;

  const target = candidate
    .slice(TEMPLATE_PREFIX.length, candidate.length - TEMPLATE_SUFFIX.length)
    .trim();
  return target ? target : null;
}

// The firmware answers { accepted, status }. Anything else means the board never
// spoke, and recording that as acceptance would hide an unreachable controller.
// n8n wraps an HTTP response in { body, headers, statusCode, statusMessage }
// when "Include Response Headers and Status" is on. The ESP32's own contract
// { accepted, status } lives inside `body` there; a bare object means the
// verdict post went through without the envelope (or in an older graph).
function readEsp32Outcome(json) {
  const error = json?.error;
  if (error !== undefined && error !== null) {
    const message = typeof error === "string" ? error : error?.message;
    return {
      esp32Accepted: null,
      esp32Status: null,
      esp32HttpStatus: null,
      esp32Error: message === undefined || message === null ? String(error) : String(message)
    };
  }

  const body =
    json && typeof json === "object" && json.body && typeof json.body === "object"
      ? json.body
      : json;
  const accepted = typeof body?.accepted === "boolean" ? body.accepted : null;
  const status =
    typeof body?.status === "string" && body.status.trim() ? body.status : null;
  const httpStatus = typeof json?.statusCode === "number" ? json.statusCode : null;

  return { esp32Accepted: accepted, esp32Status: status, esp32HttpStatus: httpStatus, esp32Error: null };
}

function orNull(value) {
  return value === undefined ? null : value;
}

function readFrameContext(frameContext) {
  if (!frameContext || typeof frameContext !== "object") {
    return { sessionId: null, sequence: null, width: null, height: null };
  }
  return {
    sessionId: orNull(frameContext.sessionId),
    sequence: orNull(frameContext.sequence),
    width: orNull(frameContext.width),
    height: orNull(frameContext.height)
  };
}

function buildInspectionRow(decision, {
  frameContext,
  inspectionTarget,
  modelInstruction,
  inspectedAt,
  frameUrl,
  itemContext
} = {}) {
  const frame = readFrameContext(frameContext);
  return {
    inspection_at: orNull(inspectedAt),
    inspection_target: orNull(inspectionTarget),
    model_instruction: orNull(modelInstruction),
    camera_session: frame.sessionId,
    frame_sequence: frame.sequence,
    frame_width: frame.width,
    frame_height: frame.height,
    box_count: decision.boxCount ?? 0,
    defect_coverage: decision.coverage ?? null,
    coverage_threshold: decision.coverageThreshold ?? null,
    verdict: decision.verdict,
    prompt_verified: decision.promptVerified ?? null,
    frame_url: orNull(frameUrl),
    controller_session: itemContext?.controller_session ?? null,
    item_id: itemContext?.item_id ?? null
  };
}

function buildControlActionRow({
  inspectionId,
  action,
  esp32Accepted,
  esp32Status,
  esp32HttpStatus,
  esp32Error,
  requestedAt,
  itemContext,
  controlOutcome,
  controlReason,
  acknowledgedControllerSession,
  acknowledgedItemId
} = {}) {
  return {
    inspection_id: orNull(inspectionId),
    action: orNull(action),
    esp32_accepted: esp32Accepted ?? null,
    esp32_status: esp32Status ?? null,
    esp32_http_status: esp32HttpStatus ?? null,
    esp32_error: esp32Error ?? null,
    requested_at: orNull(requestedAt),
    controller_session: itemContext?.controller_session ?? null,
    item_id: itemContext?.item_id ?? null,
    control_outcome: controlOutcome ?? "delivery_unknown",
    control_reason: controlReason ?? null,
    ack_controller_session: acknowledgedControllerSession ?? null,
    ack_item_id: acknowledgedItemId ?? null
  };
}

function buildPromptHistoryRow({
  changedAt,
  inspectionTarget,
  modelInstruction,
  source,
  modelHttpStatus,
  modelError
} = {}) {
  return {
    changed_at: orNull(changedAt),
    inspection_target: orNull(inspectionTarget),
    model_instruction: orNull(modelInstruction),
    source: orNull(source),
    model_http_status: orNull(modelHttpStatus),
    model_error: orNull(modelError)
  };
}

function buildSystemLogRow({
  loggedAt,
  severity,
  component,
  message,
  details
} = {}) {
  return {
    logged_at: orNull(loggedAt),
    severity: orNull(severity),
    component: orNull(component),
    message: orNull(message),
    details: details === undefined ? null : details
  };
}

function buildHudPayload({ decision, frameContext, snapshotUrl } = {}) {
  const frame = readFrameContext(frameContext);
  const verdict = decision.verdict ?? VERDICT.REJECT;

  return {
    type: HUD_MESSAGE_TYPE,
    coordinateSpace: HUD_COORDINATE_SPACE,
    status: verdict,
    reason: decision.reason ?? null,
    timestamp: frameContext?.capturedAt ?? null,
    frame: {
      // The HUD's parser reads frame.id first and uses it to order and
      // de-duplicate frames, so it is composed from the Frame Context the Pi
      // sent rather than left null. Session plus sequence is the same identity
      // the duplicate guard uses.
      id: frame.sessionId && frame.sequence !== null ? `${frame.sessionId}:${frame.sequence}` : null,
      sessionId: frame.sessionId,
      sequence: frame.sequence,
      width: frame.width,
      height: frame.height
    },
    snapshotUrl: orNull(snapshotUrl),
    detections: (decision.detections ?? []).map((detection) => ({
      label: detection.label,
      box: detection.box,
      status: verdict
    }))
  };
}



// Strings survive JSON/JavaScript without losing 64-bit controller counters.
function parsePhysicalItem(source, incoming) {
  const hasIdentity = incoming.controller_session !== undefined || incoming.item_id !== undefined;
  if (!hasIdentity && source !== "item_detected") return { item: null, error: null };
  const validToken = value => typeof value === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(value);
  const window = incoming.verdict_window_ms;
  if (!validToken(incoming.controller_session) || !validToken(incoming.item_id) ||
      !Number.isInteger(window) || window <= 0 || window > 3000) {
    return { item: null, error: "invalid_item_context" };
  }
  return { item: { controller_session: incoming.controller_session, item_id: incoming.item_id, verdict_window_ms: window }, error: null };
}

function readControlReceipt(json, item) {
  const raw = readEsp32Outcome(json);
  const body = json?.body ?? json;
  const outcome = { ...raw, controllerSession: item?.controller_session ?? null, itemId: item?.item_id ?? null,
    acknowledgedControllerSession: typeof body?.controller_session === "string" ? body.controller_session : null,
    acknowledgedItemId: typeof body?.item_id === "string" ? body.item_id : null };
  if (!item) return { ...outcome, esp32Accepted: null, controlOutcome: "not_requested", controlReason: "observational" };
  const matches = body?.controller_session === item.controller_session && body?.item_id === item.item_id;
  const successfulHttp = raw.esp32HttpStatus >= 200 && raw.esp32HttpStatus < 300;
  if (!matches || !successfulHttp || raw.esp32Accepted === null || raw.esp32Error) {
    return { ...outcome, esp32Accepted: null, controlOutcome: "delivery_unknown", controlReason: raw.esp32Error || "unverified_acknowledgement" };
  }
  return { ...outcome, controlOutcome: raw.esp32Accepted ? "accepted" : "ignored", controlReason: body.reason ?? body.status ?? "unspecified" };
}

// Physical-item records must not be suppressed because a camera reused a frame.
// The controller alone enforces actuation idempotency; this key only affects audit/HUD.
function inspectionDedupContext(frame, item) {
  return item ? { sessionId: JSON.stringify([item.controller_session, item.item_id]), sequence: 0 } : frame;
}

return [{ json: buildHealthProbe(
  'model-server',
  () => $input.first().json,
  (body) => body?.status === 'ok'
) }];

const DEFAULT_COVERAGE_THRESHOLD = 0.005;

// Controller-local expiry rejects. Leave headroom for a timely evaluated Verdict;
// snapshot upload happens after the control attempt and does not consume this budget.
const VERDICT_WINDOW_MS = 3000;
const MODEL_PROMPT_TIMEOUT_MS = 250;
const CAPTURE_TIMEOUT_MS = 800;
const SNAPSHOT_UPLOAD_TIMEOUT_MS = 300;
const MODEL_TIMEOUT_MS = 1200;
const VERDICT_POST_TIMEOUT_MS = 250;
const PRE_VERDICT_BUDGET_MS =
  MODEL_PROMPT_TIMEOUT_MS +
  CAPTURE_TIMEOUT_MS +
  MODEL_TIMEOUT_MS;

const MODEL_SUCCESS_STATUS = "success";
const DEFAULT_DETECTION_LABEL = "defect";

const VERDICT = Object.freeze({ PASS: "pass", REJECT: "reject" });

const FailureReason = Object.freeze({
  MODEL_TIMEOUT: "model_timeout",
  MODEL_UNREACHABLE: "model_unreachable",
  MODEL_HTTP_ERROR: "model_http_error",
  MODEL_INVALID_RESPONSE: "model_invalid_response",
  MODEL_STATUS_MISSING: "model_status_missing",
  MODEL_ERROR_STATUS: "model_error_status",
