  if (!Array.isArray(box) || box.length < 4) return 0;
  const coords = box.slice(0, 4).map(asFiniteNumber);
  if (coords.some((value) => value === null)) return 0;
  const [x1, y1, x2, y2] = coords;
  return Math.max(0, x2 - x1) * Math.max(0, y2 - y1);
