function buildSystemLogRow({
  loggedAt,
  severity,
  component,
  message,
  details
} = {}) {
  return {
    logged_at: orNull(loggedAt),
    severity: orNull(severity),
    component: orNull(component),
    message: orNull(message),
    details: details === undefined ? null : details
